SELECT COUNT(*) AS nintendo_switch_count
FROM nlq.listings l
WHERE (l.title ILIKE '%nintendo switch%' OR l.description ILIKE '%nintendo switch%');

SELECT COUNT(*) AS total_listings_at_iv
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT name
FROM nlq.meetup_spots
WHERE area = 'on campus';

SELECT ROUND(100.0 * SUM(CASE WHEN rent_price_per_week IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 2) AS rental_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_count
FROM nlq.listings
WHERE meetup_spot ILIKE '%pickup only%';

SELECT COUNT(*) AS listings_since_oct_1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS reviews_given
FROM nlq.my_reviews
WHERE direction = 'given';

SELECT COUNT(*) AS five_star_ratings_received
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT COUNT(*) AS total_removed_listings
FROM nlq.my_listings
WHERE status = 'removed';

SELECT COUNT(*) AS under_4_star_reviews
FROM nlq.my_reviews
WHERE direction = 'received' AND rating < 4;

SELECT COUNT(DISTINCT category) AS category_count
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

select coalesce(sum(case when my_role = 'seller' then agreed_price else -agreed_price end), 0) as net_gain
from nlq.my_deals
where status = 'completed';

SELECT MAX(agreed_price) AS highest_paid
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT round(coalesce(sum(agreed_price),0)::numeric, 2) AS total_revenue
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT ROUND(AVG(rental_deposit)::numeric, 2) AS avg_deposit
FROM nlq.deals
WHERE deal_type = 'rental' AND rental_deposit IS NOT NULL;

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT ROUND(AVG(agreed_price)::numeric, 2) AS avg_buyer_payment
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT COUNT(DISTINCT buyer_id) AS student_count
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'completed';

SELECT COUNT(DISTINCT item_id) AS distinct_items_rented
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT COUNT(*) AS reserved_count
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition = 'like_new';

SELECT COUNT(*) AS suspended_accounts
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_reports
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS report_count
FROM nlq.reports
WHERE target_type = 'listing';

select count(*) as items_rented_out
from nlq.listings_all
where status = 'rented_out';

SELECT spot_id, name, area
FROM nlq.meetup_spots
WHERE area = 'off campus';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT COUNT(*) AS buyer_sent_more_conversations
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT ROUND(100.0 * SUM(CASE WHEN rating = 5 THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_5_star_reviews
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT COUNT(*) AS students_never_posted
FROM nlq.students s
WHERE NOT EXISTS (
    SELECT 1 FROM nlq.listings_all la
    WHERE la.seller_id = s.student_id
);

SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE EXTRACT(EPOCH FROM (resolved_at - filed_at)) / 3600 / 24 <= 2) / COUNT(*)::numeric, 2) AS percent_within_48h
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS zero_bookmarked_items
FROM nlq.listings_all la
WHERE NOT EXISTS (
    SELECT 1 FROM nlq.saved_items si
    WHERE si.item_id = la.item_id
);

select count(*) as student_count
from (
  select l.seller_id
  from nlq.listings_all l
  where l.is_for_sale and l.sale_price is not null
    and not exists (
      select 1 from nlq.deals d
      where d.item_id = l.item_id
        and d.deal_type = 'sale'
        and d.status = 'completed'
    )
) sub;

select count(*) as listings_saved_by_at_least_5_but_never_sold
from (
  select s.item_id, count(distinct s.student_id) as saved_count
  from nlq.saved_items s
  group by s.item_id
) sub
where sub.saved_count >= 5
  and not exists (
    select 1 from nlq.deals d
    where d.item_id = sub.item_id
      and d.deal_type = 'sale'
      and d.status = 'completed'
  );
